299	    /** A holder's part of a claim: its amount times their share divided by 100, times the rate of the holder's
300	     *  own grade in force on its date divided by 100, rounded as the claim rounds; none (counting as 0.00, and
301	     *  keeping no figure for the holder) when their grade has no rate then. A settled claim keeps its parts as frozen: its settled figure times the share divided by 100. */
302	    public static BigDecimal part(Optional<Sheet> sheet, Claim claim, ClaimShare share, BigDecimal figure,
303	            Person holder, List<Claim> sheetClaims, List<Rate> sheetRates) {
304	        if (claim.getSettledDue() != null) {
305	            return share.part(figure);
306	        }
307	        if (holder == null) {
308	            return null;
309	        }
310	        LocalDate on = roundingDate(claim, sheetClaims);
311	        return inForce(sheetRates, holder.gradeOn(claim.getDate()), claim.getDate(), claim)
312	                .map(rate -> claim.getAmount().multiply(share.getShare()).multiply(rate.getRate()).movePointLeft(4)
313	                        .setScale(2, sheet.map(s -> s.rounding(on)).orElse(RoundingMode.HALF_EVEN)))
314	                .orElse(null);
315	    }
