411	    private Breakdown breakdown(String sheetId, LocalDate date, Snapshot snapshot, LocalDate today) {
412	        List<Person> sheetPeople = date == null ? people.findBySheetIdOrderByPositionAscIdAsc(sheetId)
413	                : asOf.people(sheetId, date);
414	        List<Claim> sheetClaims = date == null ? claims.findBySheetIdOrderByIdDesc(sheetId) : asOf.claims(sheetId, date);
415	        Map<String, BigDecimal> gradeDues = new LinkedHashMap<>();
416	        for (Person person : sheetPeople) {
417	            Figures figures = snapshot.people().get(person.getId());
418	            if (person.isRetired() || figures == null || figures.dueTotal() == null) {
419	                continue;
420	            }
421	            gradeDues.merge(person.gradeOn(today == null ? LocalDate.MAX : today), figures.dueTotal(), BigDecimal::add);
422	        }
423	        Map<ClaimStatus, Integer> statusCounts = new LinkedHashMap<>();
424	        sheetClaims.forEach(c -> statusCounts.merge(c.getStatus(), 1, Integer::sum));
425	        return new Breakdown(gradeDues, statusCounts);
426	    }
