428	    /** People's figures added up, leaving out the single highest and the single lowest when there are three
429	     *  or more. */
430	    static BigDecimal trimmed(List<BigDecimal> figures) {
431	        BigDecimal sum = figures.stream().reduce(ZERO, BigDecimal::add);
432	        if (figures.size() < 3) {
433	            return sum;
434	        }
435	        BigDecimal max = figures.stream().max(BigDecimal::compareTo).orElseThrow();
436	        BigDecimal min = figures.stream().min(BigDecimal::compareTo).orElseThrow();
437	        return sum.subtract(max).subtract(min);
438	    }
