162	    private Snapshot take(Optional<Sheet> sheet, List<Person> sheetPeople, List<Claim> sheetClaims, List<Rate> sheetRates,
163	            Map<Long, BigDecimal> cuts) {
164	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
165	        Map<Long, Figures> figures = new LinkedHashMap<>();
166	        BigDecimal claimedTotal = ZERO;
167	        List<BigDecimal> dues = new ArrayList<>();
168	        List<BigDecimal> overdues = new ArrayList<>();
169	        int sheetOverdueCount = 0;
170	        Map<Long, Person> byId = new LinkedHashMap<>();
171	        sheetPeople.forEach(p -> byId.put(p.getId(), p));
172	        for (Person person : sheetPeople) {
173	            BigDecimal claimed = ZERO;
174	            BigDecimal due = ZERO;
175	            BigDecimal overdue = ZERO;
176	            BigDecimal settled = ZERO;
177	            BigDecimal settledTotal = ZERO;
178	            BigDecimal openTotal = ZERO;
179	            int overdueCount = 0;
180	            boolean keptFigure = false;
181	            LocalDate latest = null;
182	            for (Claim claim : sheetClaims) {
183	                if (!claim.getPersonId().equals(person.getId()) || !countsClaimed(claim, person, today)) {
184	                    continue;
185	                }
186	                latest = later(latest, claim.getDate());
187	                if (claim.getCorrects() == null || claim.getCorrects().isEmpty()) {
188	                    // a claim that corrects another is left out of claimed
189	                    claimed = claimed.add(claim.getAmount());
190	                }
191	                BigDecimal kept = claim.getSettledDue() != null ? claim.getSettledDue()
192	                        : claim.isBound() ? claim.getStatedDue() : null;
193	                BigDecimal figure = null;
194	                if (kept != null) {
195	                    keptFigure = true;
196	                    figure = charged(sheet, claim, person, kept);
197	                } else if (!claim.isBound()) {
198	                    // a claim priced at the grade in force on its date keeps a figure too
199	                    BigDecimal live = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim)
200	                            .map(rate -> rated(sheet, claim, sheetClaims, rate))
201	                            .orElse(null);
202	                    if (live != null) {
203	                        keptFigure = true;
204	                        figure = charged(sheet, claim, person, live);
205	                    }
206	                }
207	                if (figure != null) {
208	                    // the parts its holders hold are theirs, not its person's
209	                    BigDecimal own = figure.subtract(sharedPart(sheet, claim, figure, byId, sheetClaims, sheetRates));
210	                    due = due.add(own);
211	                    if (claim.getStatus() == ClaimStatus.SETTLED) {
212	                        settledTotal = settledTotal.add(own);
213	                    } else if (isOpen(claim)) {
214	                        openTotal = openTotal.add(own);
215	                    }
216	                    if (overdue(sheet, claim, person, today)) {
217	                        overdue = overdue.add(figure);
218	                    }
219	                    if (claim.getStatus() == ClaimStatus.SETTLED
220	                            && (claim.getCorrects() == null || claim.getCorrects().isEmpty())) {
221	                        settled = settled.add(figure);
222	                    }
223	                }
224	                if (overdue(sheet, claim, person, today)) {
225	                    overdueCount++;
226	                }
227	            }
228	            for (Claim claim : sheetClaims) {
229	                Optional<ClaimShare> held = claim.shareOf(person.getId());
230	                Person owner = byId.get(claim.getPersonId());
231	                if (held.isEmpty() || owner == null || !countsClaimed(claim, owner, today)) {
232	                    continue;
233	                }
234	                BigDecimal figure = figure(sheet, claim, owner, sheetClaims, sheetRates);
235	                BigDecimal part = figure == null ? null
236	                        : part(sheet, claim, held.get(), figure, person, sheetClaims, sheetRates);
237	                if (part != null) {
238	                    keptFigure = true;
239	                    due = due.add(part);
240	                    if (claim.getStatus() == ClaimStatus.SETTLED) {
241	                        settledTotal = settledTotal.add(part);
242	                    } else if (isOpen(claim)) {
243	                        openTotal = openTotal.add(part);
244	                    }
245	                }
246	            }
247	            sheetOverdueCount += overdueCount;
248	            BigDecimal score = settled.subtract(BigDecimal.valueOf(500L * overdueCount))
249	                    .movePointLeft(2).setScale(0, RoundingMode.HALF_EVEN);
250	            boolean rated = today != null && inForce(sheetRates, person.gradeOn(today), today).isPresent();
251	            BigDecimal personDue = rated || keptFigure ? capped(sheet, due, cuts.get(person.getId()), latest) : null;
252	            BigDecimal cut = cuts.getOrDefault(person.getId(), ZERO);
253	            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue, overdue, score,
254	                    settledTotal, openTotal, cut == null ? ZERO : cut.setScale(2, RoundingMode.HALF_EVEN)));
255	            claimedTotal = claimedTotal.add(claimed);
256	            overdues.add(overdue);
257	            if (personDue != null) {
258	                dues.add(personDue);
259	            }
260	        }
261	        return new Snapshot(figures, claimedTotal, trimmed(dues), trimmed(overdues), sheetOverdueCount);
262	    }
