264	    /** The parts a person holds of other people's claims that count now, at the figures their due-totals count,
265	     *  added up; null when they hold no part of a claim with a figure. */
266	    public BigDecimal heldParts(String sheetId, long personId) {
267	        Optional<Sheet> sheet = sheets.findById(sheetId);
268	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
269	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
270	        List<Rate> sheetRates = rates.findWithAncestors(sheetId, sheets.ancestors(sheetId));
271	        Map<Long, Person> byId = new LinkedHashMap<>();
272	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> byId.put(p.getId(), p));
273	        BigDecimal held = null;
274	        for (Claim claim : sheetClaims) {
275	            Optional<ClaimShare> share = claim.shareOf(personId);
276	            Person owner = byId.get(claim.getPersonId());
277	            if (share.isEmpty() || owner == null || !countsClaimed(claim, owner, today)) {
278	                continue;
279	            }
280	            BigDecimal figure = figure(sheet, claim, owner, sheetClaims, sheetRates);
281	            BigDecimal part = figure == null ? null
282	                    : part(sheet, claim, share.get(), figure, byId.get(personId), sheetClaims, sheetRates);
283	            if (part != null) {
284	                held = (held == null ? ZERO : held).add(part);
285	            }
286	        }
287	        return held;
288	    }
