317	    /** A claim's figure as its person's due-total counts it: its settled due, else the figure its statement
318	     *  bound, else its live due, charged; none when it has none. */
319	    private static BigDecimal figure(Optional<Sheet> sheet, Claim claim, Person person, List<Claim> sheetClaims,
320	            List<Rate> sheetRates) {
321	        BigDecimal kept = claim.getSettledDue() != null ? claim.getSettledDue()
322	                : claim.isBound() ? claim.getStatedDue() : null;
323	        if (kept != null) {
324	            return charged(sheet, claim, person, kept);
325	        }
326	        if (claim.isBound()) {
327	            return null;
328	        }
329	        return inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim)
330	                .map(rate -> charged(sheet, claim, person, rated(sheet, claim, sheetClaims, rate)))
331	                .orElse(null);
332	    }
