346	    /** The figures of every descendant of a sheet, as {@link #descendants(String, LocalDate)}; over their rows now
347	     *  with a preview date standing in for each one's today when one is given (and no as-of date). */
348	    public Consolidated descendants(String sheetId, LocalDate date, LocalDate preview) {
349	        Set<String> seen = new LinkedHashSet<>(List.of(sheetId));
350	        List<String> todo = new ArrayList<>(List.of(sheetId));
351	        int peopleCount = 0;
352	        BigDecimal due = ZERO;
353	        BigDecimal overdue = ZERO;
354	        int overdueCount = 0;
355	        Map<String, BigDecimal> gradeDues = new LinkedHashMap<>();
356	        Map<ClaimStatus, Integer> statusCounts = new LinkedHashMap<>();
357	        List<Member> members = new ArrayList<>();
358	        while (!todo.isEmpty()) {
359	            for (Sheet child : sheets.findByParentOrderByIdAsc(todo.remove(0))) {
360	                if (!seen.add(child.getId())) {
361	                    continue;
362	                }
363	                todo.add(child.getId());
364	                Snapshot snapshot = date != null ? take(child.getId(), date)
365	                        : preview != null ? preview(child.getId(), preview) : take(child.getId());
366	                peopleCount += snapshot.people().size();
367	                due = due.add(snapshot.dueTotal());
368	                overdue = overdue.add(snapshot.overdueTotal());
369	                overdueCount += snapshot.overdueCount();
370	                Breakdown breakdown = date == null && preview != null ? breakdown(child.getId(), snapshot, preview)
371	                        : breakdown(child.getId(), date, snapshot);
372	                breakdown.gradeDueTotals().forEach((g, d) -> gradeDues.merge(g, d, BigDecimal::add));
373	                breakdown.statusCounts().forEach((st, n) -> statusCounts.merge(st, n, Integer::sum));
374	                members.addAll(members(child.getId(), date, snapshot));
375	            }
376	        }
377	        return new Consolidated(peopleCount, due, overdue, gradeDues, statusCounts, members, overdueCount);
378	    }
