388	            if (figures == null) {
389	                continue;
390	            }
391	            List<String> names = new ArrayList<>(List.of(person.getName()));
392	            names.addAll(person.getAliases());
393	            members.add(new Member(names, figures.dueTotal(), figures.overdueTotal(), figures.settledTotal(),
394	                    figures.openTotal(), figures.cutTotal()));
