440	    /** Each person's due-total of their claims due by a day from one date to another, both inclusive, by person
441	     *  id, every person on the sheet in list order, as the screen shows a person's for a
442	     *  period: a claim counts by the status it had at the end of the last day, as its status log records
443	     *  it (one added after then does not), unless a hold or a deferral leaves it out now; each counts its
444	     *  due as shown now: its settled due, else the figure its statement bound, else its live due, an
445	     *  overdue claim's late charge on top, at least the floor (a claim with no figure adds nothing). */
446	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
447	        Optional<Sheet> sheet = sheets.findById(sheetId);
448	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
449	        List<Rate> sheetRates = rates.findWithAncestors(sheetId, sheets.ancestors(sheetId));
450	        Map<Long, Person> byId = new LinkedHashMap<>();
451	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
452	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
453	            byId.put(p.getId(), p);
454	            totals.put(p.getId(), ZERO);
455	        });
456	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
457	        for (Claim claim : sheetClaims) {
458	            Person person = byId.get(claim.getPersonId());
459	            if (person == null || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)
460	                    || !countsAt(claim, to) || heldOut(claim, person, today) || claim.deferredOn(today)) {
461	                continue;
462	            }
463	            BigDecimal due;
464	            if (claim.getSettledDue() != null) {
465	                due = claim.getSettledDue();
466	            } else if (claim.isBound()) {
467	                due = claim.getStatedDue();
468	            } else {
469	                due = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim)
470	                        .map(rate -> rated(sheet, claim, sheetClaims, rate))
471	                        .orElse(null);
472	            }
473	            if (due != null) {
474	                totals.merge(person.getId(), charged(sheet, claim, person, due), BigDecimal::add);
475	            }
476	        }
477	        return totals;
478	    }
479	
480	    /** Each person's carried figure for a period, by person id, every person on the sheet in list order, as the
481	     *  screen shows it while the period is open: the due (as {@link #dueBetweenByPerson} counts it) of their
482	     *  claims not left out now by a hold or a deferral whose due-by falls in one of the sheet's periods ending
483	     *  before this one starts, and that were still OPEN or PENDING at the end of this period's last day, as
484	     *  their status log records it; and their opening balance for the period on top. */
485	    public Map<Long, BigDecimal> carriedByPerson(String sheetId, Period period, List<Period> sheetPeriods) {
486	        Optional<Sheet> sheet = sheets.findById(sheetId);
487	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
488	        List<Rate> sheetRates = rates.findWithAncestors(sheetId, sheets.ancestors(sheetId));
489	        Map<Long, Person> byId = new LinkedHashMap<>();
490	        Map<Long, BigDecimal> carried = new LinkedHashMap<>();
491	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
492	            byId.put(p.getId(), p);
493	            carried.put(p.getId(), ZERO);
494	        });
495	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
496	        for (Claim claim : sheetClaims) {
497	            Person person = byId.get(claim.getPersonId());
498	            if (person == null || claim.getDueBy() == null || heldOut(claim, person, today) || claim.deferredOn(today)) {
499	                continue;
500	            }
501	            Optional<Period> own = sheetPeriods.stream().filter(p -> p.contains(claim.getDueBy())).findFirst();
502	            if (own.isEmpty() || !own.get().getToDate().isBefore(period.getFromDate())) {
503	                continue;
504	            }
505	            ClaimStatus status = statusAt(claim, period.getToDate());
506	            if (status == null || !status.isOpen()) {
507	                continue;
508	            }
509	            BigDecimal due;
510	            if (claim.getSettledDue() != null) {
511	                due = claim.getSettledDue();
512	            } else if (claim.isBound()) {
513	                due = claim.getStatedDue();
514	            } else {
515	                due = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim)
516	                        .map(rate -> rated(sheet, claim, sheetClaims, rate))
517	                        .orElse(null);
518	            }
519	            if (due != null) {
520	                carried.merge(person.getId(), charged(sheet, claim, person, due), BigDecimal::add);
521	            }
522	        }
523	        period.getOpenings().forEach((id, opening) -> carried.computeIfPresent(id, (k, c) -> c.add(opening)));
524	        return carried;
525	    }
526	
527	    /** Each person's open figure at the end of a day, by person id, every person on the sheet in list order: the
528	     *  due (as {@link #carriedByPerson} counts it) of their claims not left out now by a hold or a deferral whose
529	     *  due-by falls in one of the given periods, and that were OPEN or PENDING at the end of the day, as their
530	     *  status log records it. */
531	    public Map<Long, BigDecimal> openByPerson(String sheetId, List<Period> inPeriods, LocalDate day) {
532	        Optional<Sheet> sheet = sheets.findById(sheetId);
533	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
534	        List<Rate> sheetRates = rates.findWithAncestors(sheetId, sheets.ancestors(sheetId));
535	        Map<Long, Person> byId = new LinkedHashMap<>();
536	        Map<Long, BigDecimal> open = new LinkedHashMap<>();
537	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
538	            byId.put(p.getId(), p);
539	            open.put(p.getId(), ZERO);
540	        });
541	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
542	        for (Claim claim : sheetClaims) {
543	            Person person = byId.get(claim.getPersonId());
544	            if (person == null || claim.getDueBy() == null || heldOut(claim, person, today) || claim.deferredOn(today)
545	                    || inPeriods.stream().noneMatch(p -> p.contains(claim.getDueBy()))) {
546	                continue;
547	            }
548	            ClaimStatus status = statusAt(claim, day);
549	            if (status == null || !status.isOpen()) {
550	                continue;
551	            }
552	            BigDecimal due;
553	            if (claim.getSettledDue() != null) {
554	                due = claim.getSettledDue();
555	            } else if (claim.isBound()) {
556	                due = claim.getStatedDue();
557	            } else {
558	                due = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim)
559	                        .map(rate -> rated(sheet, claim, sheetClaims, rate))
560	                        .orElse(null);
561	            }
562	            if (due != null) {
563	                open.merge(person.getId(), charged(sheet, claim, person, due), BigDecimal::add);
564	            }
565	        }
566	        return open;
567	    }
568	
569	    /** Record, once the change commits, a SNAPSHOT line of each person's due-total in a snapshot, in the
570	     *  list order. */
571	    public void recordSnapshot(String sheetId, String user, Snapshot snapshot) {
572	        String prefix = " sheet=" + sheetId + " by=" + user;
573	        snapshot.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT" + prefix
574	                + " name=" + figures.name() + " due-total=" + show(figures.dueTotal())));
575	    }
576	
577	    /** Record, once the change commits, a SCORE line of each person's score in a snapshot, in the list order. */
578	    public void recordScores(String sheetId, String user, Snapshot snapshot) {
579	        String prefix = " sheet=" + sheetId + " by=" + user;
580	        snapshot.people().values().forEach(figures -> audit.recordOnCommit("SCORE" + prefix
581	                + " name=" + figures.name() + " score=" + figures.score().toPlainString()));
582	    }
583	
584	    /** Record, once the change commits, a ROLLUP line of every person's figures in the list order, then the
585	     *  TOTALS line, whether or not they moved. */
586	    public void recordAll(String sheetId, String user) {
587	        Snapshot now = take(sheetId);
588	        String prefix = " sheet=" + sheetId + " by=" + user;
589	        now.people().values().forEach(figures -> audit.recordOnCommit("ROLLUP" + prefix + " person=" + figures.name()
590	                + " claimed=" + figures.claimed().toPlainString() + " due-total=" + show(figures.dueTotal())
591	                + " overdue-total=" + figures.overdueTotal().toPlainString()));
592	        audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + now.claimedTotal().toPlainString()
593	                + " due-total=" + now.dueTotal().toPlainString()
594	                + " overdue-total=" + now.overdueTotal().toPlainString());
595	        recordAlerts(sheetId, prefix, null, now);
596	    }
597	
598	    /** Record, once the change commits, the lines for every figure that moved since {@code before}. */
599	    public void recordChanges(String sheetId, String user, Snapshot before) {
600	        Snapshot after = take(sheetId);
601	        String prefix = " sheet=" + sheetId + " by=" + user;
602	        after.people().forEach((id, now) -> {
603	            Figures was = before.people().get(id);
604	            if (was == null || was.claimed().compareTo(now.claimed()) != 0
605	                    || !sameDue(was.dueTotal(), now.dueTotal())
606	                    || was.overdueTotal().compareTo(now.overdueTotal()) != 0) {
607	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
608	                        + " claimed=" + now.claimed().toPlainString() + " due-total=" + show(now.dueTotal())
609	                        + " overdue-total=" + now.overdueTotal().toPlainString());
610	            }
611	        });
612	        if (before.claimedTotal().compareTo(after.claimedTotal()) != 0
613	                || before.dueTotal().compareTo(after.dueTotal()) != 0
614	                || before.overdueTotal().compareTo(after.overdueTotal()) != 0) {
615	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal().toPlainString()
616	                    + " due-total=" + after.dueTotal().toPlainString()
617	                    + " overdue-total=" + after.overdueTotal().toPlainString());
618	        }
619	        recordAlerts(sheetId, prefix, before, after);
620	    }
621	
622	    /** Record, once the change commits, an ALERT line for each person whose due-total went from at or below the
623	     *  sheet's alert threshold (or none, or new to the sheet) to above it, in the list order; none when the
624	     *  threshold is off. */
625	    private void recordAlerts(String sheetId, String prefix, Snapshot before, Snapshot after) {
626	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
627	        if (threshold == null) {
628	            return;
629	        }
630	        after.people().forEach((id, now) -> {
631	            Figures was = before == null ? null : before.people().get(id);
632	            if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
633	                audit.recordOnCommit("ALERT" + prefix + " name=" + now.name() + " due-total=" + show(now.dueTotal()));
634	            }
635	        });
636	    }
637	
638	    private static boolean above(BigDecimal dueTotal, BigDecimal threshold) {
639	        return dueTotal != null && dueTotal.compareTo(threshold) > 0;
640	    }
641	
642	    private static boolean isOpen(Claim claim) {
643	        return claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.PENDING;
644	    }
645	
646	    /** Whether a claim counts toward claimed: its status counts, it is not left out by its person's
647	     *  retirement (a hold leaves it in), and it is not deferred past the sheet's today. */
648	    private static boolean countsClaimed(Claim claim, Person person, LocalDate today) {
649	        return claim.getStatus().counts() && !retiredOut(claim, person, today) && !claim.deferredOn(today);
650	    }
651	
652	    /** Whether a claim counted by the status it had at the end of a day, as its status log records it:
653	     *  its latest line dated on or before it; not when it was added after it. A claim with no log counts
654	     *  by its status now. */
655	    private static boolean countsAt(Claim claim, LocalDate day) {
656	        ClaimStatus status = statusAt(claim, day);
657	        return status != null && status.counts();
658	    }
659	
660	    /** The status a claim had at the end of a day, as its status log records it: its latest line dated on or
661	     *  before it; none when it was added after it. A claim with no log has its status now. */
662	    private static ClaimStatus statusAt(Claim claim, LocalDate day) {
663	        List<StatusChange> log = claim.getStatusLog();
664	        if (log.isEmpty()) {
665	            return claim.getStatus();
666	        }
667	        ClaimStatus status = null;
668	        for (StatusChange change : log) {
669	            if (!change.getOn().isAfter(day)) {
670	                status = change.getStatus();
671	            }
672	        }
673	        return status;
674	    }
675	
676	    /** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus the grace days of its
677	     *  person's grade in force on its date before the sheet's today. */
678	    private static boolean overdue(Optional<Sheet> sheet, Claim claim, Person person, LocalDate today) {
679	        return claim.getStatus().isOpen() && !claim.deferredOn(today) && today != null && claim.getDueBy() != null
680	                && lateFrom(sheet, claim, person).isBefore(today);
681	    }
682	
683	    /** The date a claim's lateness runs from: its due-by plus the grace days in force on its date of its
684	     *  person's grade in force then. */
685	    public static LocalDate lateFrom(Optional<Sheet> sheet, Claim claim, Person person) {
686	        String grade = person == null ? null : person.gradeOn(claim.getDate());
687	        return sheet.map(s -> s.lateFrom(claim.getDueBy(), grade, claim.getDate())).orElse(claim.getDueBy());
688	    }
689	
690	    /** Whether a retirement leaves a claim out of claimed: it is OPEN or PENDING, bound by no statement, and
691	     *  its person's retirement date is reached on the sheet's today. */
692	    private static boolean retiredOut(Claim claim, Person person, LocalDate today) {
693	        return person != null && claim.getStatus().isOpen() && !claim.isBound() && person.retiredBy(today);
694	    }
695	
696	    /** Whether a retirement leaves a claim out of the live totals: it is OPEN or PENDING, bound by no
697	     *  statement, and its person's retirement date is reached on the sheet's today. A hold no longer does:
698	     *  it only takes a person's cut out of the pools. */
699	    public static boolean heldOut(Claim claim, Person person, LocalDate today) {
700	        return retiredOut(claim, person, today);
701	    }
702	
703	    /** A claim's amount at a rate, divided by 100, rounded to cents as the claim's rounding date rounds on
704	     *  the sheet (half to even with no sheet). */
705	    public static BigDecimal rated(Optional<Sheet> sheet, Claim claim, List<Claim> sheetClaims, Rate rate) {
706	        LocalDate on = roundingDate(claim, sheetClaims);
707	        return claim.getAmount().multiply(rate.getRate()).movePointLeft(2)
708	                .setScale(2, sheet.map(s -> s.rounding(on)).orElse(RoundingMode.HALF_EVEN));
709	    }
710	
711	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it
712	     *  corrects (the claim of the same person with that number), its own when that is not found. */
713	    public static LocalDate roundingDate(Claim claim, List<Claim> sheetClaims) {
714	        if (!claim.isCorrection()) {
715	            return claim.getDate();
716	        }
717	        return sheetClaims.stream()
718	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
719	                .findFirst().map(Claim::getDate).orElse(claim.getDate());
720	    }
721	
722	    /** A claim's due from its figure: at least the sheet's floor in force on its date, then its late charge,
723	     *  worked out on that floored figure, on top while it is OPEN or PENDING (only those go overdue). A settled claim's due is frozen (it
724	     *  already holds the charge and floor fixed when it was settled), as is a bound one's (its statement bound
725	     *  the due as shown then, charge and floor included); a correction has neither late charge nor floor, and a
726	     *  waived claim no late charge. */
727	    public static BigDecimal charged(Optional<Sheet> sheet, Claim claim, Person person, BigDecimal figure) {
728	        if (claim.getSettledDue() != null || claim.isBound() || claim.isCorrection()) {
729	            return figure;
730	        }
731	        return sheet.map(s -> {
732	                    BigDecimal floored = s.floored(figure, claim.getDate());
733	                    return claim.getStatus().isOpen() && !claim.isWaived()
734	                            ? floored.add(s.lateCharge(floored, lateFrom(sheet, claim, person), claim.getDate())) : floored;
735	                })
736	                .orElse(figure);
737	    }
738	
739	    /** A person's due-total at most the cap in force on the date of their latest claim that counts (none: the
740	     *  sheet's today) less their cut total. */
741	    private static BigDecimal capped(Optional<Sheet> sheet, BigDecimal dueTotal, BigDecimal cutTotal, LocalDate latest) {
742	        return sheet.map(s -> s.capped(dueTotal, cutTotal, latest)).orElse(dueTotal);
743	    }
744	
745	    /** The later of two dates; the other when one is none. */
746	    public static LocalDate later(LocalDate a, LocalDate b) {
747	        return a == null || (b != null && b.isAfter(a)) ? b : a;
748	    }
749	
750	    private static boolean sameDue(BigDecimal a, BigDecimal b) {
751	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
752	    }
753	
754	    private static String show(BigDecimal due) {
755	        return due == null ? "n/a" : due.toPlainString();
756	    }
757	
758	    /** The grade's rate in force on a date for a claim: as {@link #inForce(List, String, LocalDate)}, each rate
759	     *  as it applies to the claim (a forward-only rate not to a claim already on the sheet when it was saved,
760	     *  which keeps what applied to it). */
761	    public static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date, Claim claim) {
762	        List<Rate> forClaim = new ArrayList<>();
763	        sheetRates.forEach(r -> r.forClaim(claim.getId()).ifPresent(forClaim::add));
764	        return inForce(forClaim, grade, date);
765	    }
766	
767	    /** The grade's rate in force on a date: the latest from-date on or before it, none first; none
768	     *  when the date is after that rate's to-date. The rates may be a sheet's followed by its ancestors',
769	     *  nearest first: the first sheet, in that order, with a rate of the grade in force then gives it. */
770	    public static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
771	        Set<String> sheetIds = new LinkedHashSet<>();
772	        sheetRates.forEach(r -> sheetIds.add(r.getSheetId()));
773	        for (String sheetId : sheetIds) {
774	            Optional<Rate> found = inForceOn(sheetRates, sheetId, grade, date);
775	            if (found.isPresent()) {
776	                return found;
777	            }
778	        }
779	        return Optional.empty();
780	    }
781	
782	    private static Optional<Rate> inForceOn(List<Rate> sheetRates, String sheetId, String grade, LocalDate date) {
783	        return sheetRates.stream()
784	                .filter(r -> r.getSheetId().equals(sheetId) && r.getGrade().equals(grade))
785	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
786	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
787	                .filter(r -> r.coversThrough(date));
788	    }
789	}
