import net.officefloor.hq.app.history.History;

/** A claim by a person on a sheet: an amount (two decimals), a date, a note, a status and, once opened,
 *  a number and who opened it. A negative amount is a correction, naming the number of the claim it corrects. */
@Entity
@EntityListeners(History.class)
@Table(name = "claim")
public class Claim {

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    public boolean isStated() {
        return stated;
    }

    /** Bound by its person's last statement now: stated (a PENDING claim too: it shows and totals the bound
     *  figure, as any other claim that counts). */
    public boolean isBound() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Bind the claim to a figure (none for n/a), or unbind it. */
    public void setStated(boolean stated, BigDecimal statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    /** Deferred on a day: counting by its status, bound by no statement, with a deferred-until date after it.
     *  While a statement binds it the deferral waits: it counts, can be settled and stays bound; once the
     *  binding ends (the statement is cancelled, or the next one leaves it unbound) the deferral takes effect.
     *  From its date on it is a claim like any other. */
    public boolean deferredOn(LocalDate today) {
        return status.counts() && !stated && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    public int getProofs() {
        return proofs;
    }
    }

    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    public void setRemindedOn(LocalDate remindedOn) {
        this.remindedOn = remindedOn;
    }

    public boolean isEscalated() {
        return escalated;
    }

    public void setEscalated(boolean escalated) {
        this.escalated = escalated;
    }

    public boolean isWaived() {
        return waived;
    }

    public void setWaived(boolean waived) {
        this.waived = waived;
    }

    public boolean isDueBySet() {
        return dueBySet;
    }

    public void setDueBySet(boolean dueBySet) {
        this.dueBySet = dueBySet;
    }

    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }

    public String getReviewAssignee() {
        return reviewAssignee;
    }

    public void setReviewAssignee(String reviewAssignee) {
        this.reviewAssignee = reviewAssignee;
    }

    public List<StatusChange> getStatusLog() {
        return List.copyOf(statusLog);
    }

package net.officefloor.hq.app.claim;


/** A share of a claim: another person on the sheet holding a percent (two decimals, above 0.00) of its due. */
@Embeddable
public class ClaimShare {

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "share_pct", nullable = false)
    private BigDecimal share;

    protected ClaimShare() {
    }

    public ClaimShare(Long personId, BigDecimal share) {
        this.personId = personId;
        this.share = share;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getShare() {
        return share;
    }

    /** The holder's part of a due: the due times the share divided by 100, rounded half to even to cents. */
    public BigDecimal part(BigDecimal due) {
        return due.multiply(share).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }
}

