 *  none. */
public BigDecimal capped(BigDecimal dueTotal, BigDecimal cutTotal, LocalDate latest) {
    BigDecimal limit = capLess(cutTotal, latest);
    return dueTotal == null || limit == null ? dueTotal : dueTotal.min(limit);
}

