@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /** A person as the screen shows it, with how many statements were taken of them and the last one's
     *  due-total (n/a when it was) and date; none of either before their first statement; and the ids
     *  of their patrons. Their grade is the one in force on the sheet's today, and terms their own terms
     *  in force then (baseTerms those from the beginning of time, datedTerms those from a date); grades lists every grade
     *  they were given, each with its from-date (YYYY-MM-DD, none for the first); watched says whether
     *  the signed-in user watches them; clashing says whether their name or an alias is used on another sheet
     *  of the sheet's tree; origin is the sheet they were transferred from, null for anyone else. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version, int statementCount,
            String statedTotal, String statementDate, boolean retired, String retiredFrom,
            List<RetirementView> retirements,
            boolean held, List<HoldView> holds, List<Long> patronIds, boolean watched, Integer terms, Integer baseTerms,
            List<TermsView> datedTerms, String contact,
            List<String> aliases, boolean clashing, String origin, List<String> tags, List<String> snapshots,
            List<String> statementLines, String flag, String approver) {

        public static PersonView of(Person person, LocalDate today, List<Statement> statements, List<Long> patronIds,
                boolean watched, boolean clashing, List<PersonSnapshot> snapshots) {
            Statement last = statements.isEmpty() ? null : statements.get(statements.size() - 1);
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(GradeView::of).toList(), person.getVersion(),
                    statements.size(),
                    last == null ? null : last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString(),
                    last == null ? null : last.getTakenOn().toString(),
                    person.isRetired(), person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(),
                    person.getRetirements().stream().map(RetirementView::of).toList(),
                    person.isHeld(), person.getHolds().stream().map(HoldView::of).toList(), patronIds,
                    watched, person.termsOn(today), person.getTerms(),
                    person.getDatedTerms().stream().map(TermsView::of).toList(), person.getContact(), person.getAliases(), clashing,
                    person.getOriginSheet(), person.getTags(), snapshots.stream().map(PersonSnapshot::line).toList(),
                    statementLines(statements), person.flagShownOn(today), person.getApprover());
        }

        /** One line per statement standing, in the order they were taken (one taken as of an earlier date
         *  where it was taken, not by that date), as `<date> <due-total>` (n/a when it was). */
        private static List<String> statementLines(List<Statement> statements) {
            return statements.stream().sorted(Comparator.comparing(Statement::getId))
                    .map(s -> s.getTakenOn() + " " + (s.getDueTotal() == null ? "n/a" : s.getDueTotal().toPlainString()))
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /** A claim as the screen shows it: the amount with two decimals, the date YYYY-MM-DD, no number unless settled (or numbered before that rule),
     *  the due fixed when it was settled (none while its due is live)
     *  who opened it (none while a draft), whether its person's last statement bound it and the figure
     *  it bound (none while unbound, or when that was n/a), and the number a correction corrects (none
     *  otherwise), its status log, oldest first, and the date it is deferred until (none when never deferred), its proofs count and how many of them are receipts and photos,
     *  the user whose editor is open on it (none while unlocked), and whether it was added while its period
     *  was soft-closed, and the last day it was reminded (none when never), and its external reference (none when
     *  not given), and its tags, sorted, and its comments, in the order written, and its lines, in the order added, and whether its late charge is waived, and whether it is held, and its shares, in the order shared, and the user its review is assigned to (none when never assigned). */
    public record ClaimView(long id, long personId, String amount, String date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue, String corrects, String dueBy, List<StatusLine> statusLog, String deferredUntil,
            int proofs, int proofReceipts, int proofPhotos, String splitFrom, String lockedBy, boolean lateEntry,
            String remindedOn, String ref, List<String> tags, String voidReason,
            List<CommentLine> comments, Integer settleBatch, List<LineView> lines, boolean waived, boolean held,
            List<ShareView> shares, String reviewAssignee) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate().toString(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getDueBy().toString(),
                    claim.getStatusLog().stream().map(StatusLine::of).toList(),
                    claim.getDeferredUntil() == null ? null : claim.getDeferredUntil().toString(),
                    claim.getProofs(), claim.getProofs(ProofKind.RECEIPT), claim.getProofs(ProofKind.PHOTO),
                    claim.getSplitFrom(), claim.getLockedBy(),
                    claim.isLateEntry(),
                    claim.getRemindedOn() == null ? null : claim.getRemindedOn().toString(), claim.getRef(),
                    claim.getTags(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentLine::of).toList(), claim.getSettleBatch(),
                    claim.getLines().stream().map(LineView::of).toList(), claim.isWaived(), claim.isHeld(),
                    claim.getShares().stream().map(ShareView::of).toList(), claim.getReviewAssignee());
        }
    }

